import Database from "better-sqlite3";
import { openSqliteConnection, type SqliteConnectionInput } from "./sqlite-connection.js";
import type {
  Notification,
  NotificationChannel,
  NotificationChannelStatus,
  NotificationListFilter,
  NotificationPriority,
  NotificationReadStatus,
  NotificationRepository,
} from "@mezan/domain";

/**
 * SQLite-backed {@link NotificationRepository} — one row per (rule match ×
 * recipient), generated by `NotificationRulesEngine`. `channels_json`,
 * `channel_status_json` and `payload_json` are JSON text; the panel's
 * "unread" filter is a plain indexed lookup, not a computed scan.
 */

const CREATE_TABLES = `
CREATE TABLE IF NOT EXISTS notification (
  id                    TEXT PRIMARY KEY,
  rule_id               TEXT,
  recipient_user_id     TEXT NOT NULL,
  event_code            TEXT NOT NULL,
  title                 TEXT NOT NULL,
  body                  TEXT NOT NULL,
  priority              TEXT NOT NULL,
  channels_json         TEXT NOT NULL,
  channel_status_json   TEXT NOT NULL,
  status                TEXT NOT NULL,
  payload_json          TEXT NOT NULL,
  created_at            TEXT NOT NULL,
  read_at               TEXT
);
CREATE INDEX IF NOT EXISTS idx_notification_recipient ON notification(recipient_user_id, created_at);
CREATE INDEX IF NOT EXISTS idx_notification_recipient_status ON notification(recipient_user_id, status);
`;

interface NotificationRow {
  id: string;
  rule_id: string | null;
  recipient_user_id: string;
  event_code: string;
  title: string;
  body: string;
  priority: string;
  channels_json: string;
  channel_status_json: string;
  status: string;
  payload_json: string;
  created_at: string;
  read_at: string | null;
}

function toRow(n: Notification) {
  return {
    id: n.id,
    rule_id: n.ruleId,
    recipient_user_id: n.recipientUserId,
    event_code: n.eventCode,
    title: n.title,
    body: n.body,
    priority: n.priority,
    channels_json: JSON.stringify(n.channels),
    channel_status_json: JSON.stringify(n.channelStatus),
    status: n.status,
    payload_json: JSON.stringify(n.payload),
    created_at: n.createdAt,
    read_at: n.readAt,
  };
}

function fromRow(row: NotificationRow): Notification {
  return {
    id: row.id,
    ruleId: row.rule_id,
    recipientUserId: row.recipient_user_id,
    eventCode: row.event_code,
    title: row.title,
    body: row.body,
    priority: row.priority as NotificationPriority,
    channels: JSON.parse(row.channels_json) as NotificationChannel[],
    channelStatus: JSON.parse(row.channel_status_json) as Record<string, NotificationChannelStatus>,
    status: row.status as NotificationReadStatus,
    payload: JSON.parse(row.payload_json) as Record<string, unknown>,
    createdAt: row.created_at,
    readAt: row.read_at,
  };
}

class SqliteNotificationRepository implements NotificationRepository {
  private readonly insertStmt: Database.Statement;
  private readonly selectByIdStmt: Database.Statement;
  private readonly markReadStmt: Database.Statement;
  private readonly markAllReadStmt: Database.Statement;
  private readonly countUnreadStmt: Database.Statement;
  private readonly listQueuedStmt: Database.Statement;

  constructor(private readonly sqlite: Database.Database) {
    this.insertStmt = sqlite.prepare(`
      INSERT INTO notification
        (id, rule_id, recipient_user_id, event_code, title, body, priority, channels_json, channel_status_json, status, payload_json, created_at, read_at)
      VALUES
        (@id, @rule_id, @recipient_user_id, @event_code, @title, @body, @priority, @channels_json, @channel_status_json, @status, @payload_json, @created_at, @read_at)
      ON CONFLICT(id) DO UPDATE SET
        channel_status_json = @channel_status_json, status = @status, read_at = @read_at
    `);
    this.listQueuedStmt = sqlite.prepare(
      `SELECT * FROM notification WHERE channel_status_json LIKE '%"queued"%' ORDER BY created_at ASC LIMIT ?`,
    );
    this.selectByIdStmt = sqlite.prepare(`SELECT * FROM notification WHERE id = ?`);
    this.markReadStmt = sqlite.prepare(
      `UPDATE notification SET status = 'read', read_at = ? WHERE id = ? AND recipient_user_id = ? AND status = 'unread'`,
    );
    this.markAllReadStmt = sqlite.prepare(
      `UPDATE notification SET status = 'read', read_at = ? WHERE recipient_user_id = ? AND status = 'unread'`,
    );
    this.countUnreadStmt = sqlite.prepare(
      `SELECT COUNT(*) AS n FROM notification WHERE recipient_user_id = ? AND status = 'unread'`,
    );
  }

  async save(notification: Notification): Promise<void> {
    // Upsert, not insert: the dispatcher saves the SAME notification back with
    // a rewritten channel status, and an insert-only save made draining a
    // queue impossible without a second write path.
    this.insertStmt.run(toRow(notification));
  }

  /**
   * Every notification with at least one channel still `"queued"`, oldest
   * first — the dispatcher's input.
   *
   * Matched on the JSON text rather than through a column: `channel_status` is
   * a small object keyed by channel, adding a column per channel would need a
   * migration for every future one, and this runs over the drain batch only.
   */
  async listQueued(limit: number): Promise<readonly Notification[]> {
    const rows = this.listQueuedStmt.all(limit) as NotificationRow[];
    return rows.map(fromRow);
  }

  async findById(id: string): Promise<Notification | null> {
    const row = this.selectByIdStmt.get(id) as NotificationRow | undefined;
    return row ? fromRow(row) : null;
  }

  async listForUser(userId: string, filter: NotificationListFilter = {}): Promise<readonly Notification[]> {
    const clauses = ["recipient_user_id = ?"];
    const params: unknown[] = [userId];
    if (filter.status !== undefined) {
      clauses.push("status = ?");
      params.push(filter.status);
    }
    const limitClause = filter.limit !== undefined ? `LIMIT ${Math.trunc(filter.limit)}` : "";
    const rows = this.sqlite
      .prepare(`SELECT * FROM notification WHERE ${clauses.join(" AND ")} ORDER BY created_at DESC ${limitClause}`)
      .all(...params) as NotificationRow[];
    return rows.map(fromRow);
  }

  async countUnread(userId: string): Promise<number> {
    const row = this.countUnreadStmt.get(userId) as { n: number };
    return row.n;
  }

  async markRead(id: string, userId: string, readAt: string): Promise<void> {
    this.markReadStmt.run(readAt, id, userId);
  }

  async markAllRead(userId: string, readAt: string): Promise<void> {
    this.markAllReadStmt.run(readAt, userId);
  }
}

export interface SqliteNotificationStoreHandle extends NotificationRepository {
  /** Every notification with a channel still queued — the dispatcher's input (ROADMAP §3.3). */
  listQueued(limit: number): Promise<readonly Notification[]>;
  close(): void;
}

/** Open a SQLite-backed NotificationRepository. ":memory:" for tests, a path (or a shared connection) for real. */
export function createSqliteNotificationStore(path: SqliteConnectionInput = ":memory:"): SqliteNotificationStoreHandle {
  const { sqlite, owned } = openSqliteConnection(path);
  sqlite.exec(CREATE_TABLES);
  const repo = new SqliteNotificationRepository(sqlite);
  return Object.assign(repo, {
    close: () => {
      if (owned) sqlite.close();
    },
  }) as SqliteNotificationStoreHandle;
}
